// From maglev/maglev-ir.h
class TryOnStackReplacement : public FixedInputNodeT<1, TryOnStackReplacement> {
 public:
  explicit TryOnStackReplacement(uint64_t bitfield, int32_t loop_depth,
                                 FeedbackSlot feedback_slot,
                                 BytecodeOffset osr_offset,
                                 MaglevCompilationUnit* unit)
      : Base(bitfield),
        loop_depth_(loop_depth),
        feedback_slot_(feedback_slot),
        osr_offset_(osr_offset),
        unit_(unit) {}

  // From maglev/maglev-ir.cc
namespace {
void AttemptOnStackReplacement(MaglevAssembler* masm,
                               ZoneLabelRef no_code_for_osr,
                               TryOnStackReplacement* node, Register scratch0,
                               Register scratch1, int32_t loop_depth,
                               FeedbackSlot feedback_slot,
                               BytecodeOffset osr_offset) {
  // Two cases may cause us to attempt OSR, in the following order:
  //
  // 1) The osr_urgency exceeds the current loop_depth, signaling an OSR
  //    request. Call into runtime to compile.
  // 2) maybe_has_optimized_osr_code is true, and we have already compiled
  //    OSR'd code. Load and jump to it.
  //
  // Note that (1) may happen concurrently with compilation of OSR'd code, in
  // which case we will just request compilation again, which is fine.
  using FV = FeedbackVector;
  Tagged<FeedbackVector> vector =
      node->unit()->feedback().value().object();
  __ LoadTaggedField(
      scratch0,
      FieldMemOperand(scratch0, JSFunction::kFeedbackVectorOffset));
  __ Ldrsb(scratch1, FieldMemOperand(scratch0, FV::kOsrStateOffset));
  __ DecodeField<FV::MaybeHasOptimizedOsrCodeBit>(scratch1);
  __ JumpIfByte(kNotEqual, scratch1, 0, &has_osr_code);

  // Check osr_urgency.
  __ Ldrsb(scratch1, FieldMemOperand(scratch0, FV::kOsrStateOffset));
  __ DecodeField<FV::OsrUrgencyBit>(scratch1);
  // The osr_urgency exceeds the current loop_depth, signaling an OSR
  // request. Call into runtime to compile.
  {
    // ...
  }

  __ Bind(&has_osr_code);
  // We have OSR'd code. Load it and jump to it.
  // ...
}

// From maglev/maglev-graph-builder.cc
if (ShouldEmitOsrInterruptBudgetChecks()) {
  RETURN_IF_ABORT(AddNewNode<TryOnStackReplacement>(
      {GetClosure()}, loop_offset, feedback_slot,
      BytecodeOffset(iterator_.current_offset()), compilation_unit_));
}
